insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pm-kisan','central','agriculture','பிரதமர் கிசான் சம்மான் நிதி (PM-KISAN)','PM-KISAN Samman Nidhi','வேளாண்மை & விவசாயிகள் நலத் துறை (மத்திய அரசு)','Dept. of Agriculture & Farmers Welfare (Govt of India)','தகுதியுள்ள நில உரிமை விவசாயக் குடும்பங்களுக்கு ஆண்டுக்கு ₹6,000, மூன்று தவணைகளில் நேரடியாக வங்கிக் கணக்கில்.','₹6,000 a year in three instalments, paid directly to the bank account of eligible landholding farmer families.','{"minAge":null,"maxAge":null,"gender":"any","occupations":["farmer"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","land","mobile"]'::jsonb,'pmkisan.gov.in-இல் ''Farmers Corner'' → புதிய பதிவு; அல்லது இ-சேவை / CSC மையம்.','Register under ''Farmers Corner'' on pmkisan.gov.in, or at an e-Sevai / CSC centre.','https://pmkisan.gov.in',array['farming','money']::text[],array['kisan','farmer','விவசாயி','கிசான்','6000']::text[],10,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pmfby','central','agriculture','பிரதமர் பசல் பீமா யோஜனா (பயிர்க் காப்பீடு)','PM Fasal Bima Yojana (crop insurance)','வேளாண்மை & விவசாயிகள் நலத் துறை','Dept. of Agriculture & Farmers Welfare','இயற்கைச் சீற்றம், பூச்சி, நோயால் பயிர் இழப்பு ஏற்பட்டால் குறைந்த பிரீமியத்தில் காப்பீடு.','Insurance cover against crop loss from calamities, pests and disease at a low farmer premium.','{"minAge":null,"maxAge":null,"gender":"any","occupations":["farmer"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","land"]'::jsonb,'பயிர்க் கடன் வழங்கும் வங்கி / கூட்டுறவுச் சங்கம், CSC அல்லது pmfby.gov.in வழியாக, அறிவிக்கப்பட்ட கடைசித் தேதிக்குள்.','Through your crop-loan bank / co-operative society, a CSC or pmfby.gov.in before the notified cut-off date.','https://pmfby.gov.in',array['farming','insurance']::text[],array['crop insurance','பயிர் காப்பீடு','pmfby']::text[],8,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('kcc','central','agriculture','கிசான் கிரெடிட் கார்டு (KCC)','Kisan Credit Card (KCC)','வங்கிகள் / கூட்டுறவு வங்கிகள் (NABARD வழிகாட்டுதல்)','Banks / co-operative banks (NABARD guidelines)','விவசாயத்துக்குத் தேவையான குறுகிய காலக் கடன் எளிய நடைமுறையில்.','Short-term farm credit through a simple process.','{"minAge":null,"maxAge":null,"gender":"any","occupations":["farmer"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","land","photo"]'::jsonb,'உங்கள் வங்கிக் கிளை அல்லது கூட்டுறவு வங்கியில் விண்ணப்பம்.','Apply at your bank branch or co-operative bank.','https://www.nabard.org',array['farming','loan']::text[],array['kcc','kisan credit','விவசாயக் கடன்','farm loan','farmer loan','crop loan','விவசாயி கடன்','விவசாயக் கடன்','loan']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('soil-health-card','central','agriculture','மண் வள அட்டை','Soil Health Card','வேளாண்மை & விவசாயிகள் நலத் துறை','Dept. of Agriculture & Farmers Welfare','மண் பரிசோதனை அடிப்படையில் எந்த உரம், எவ்வளவு என்ற பரிந்துரை.','Soil-test based advice on which fertiliser and how much to use.','{"minAge":null,"maxAge":null,"gender":"any","occupations":["farmer"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","land"]'::jsonb,'உங்கள் வட்டார வேளாண்மை அலுவலகம் அல்லது soilhealth.dac.gov.in.','Your block agriculture office or soilhealth.dac.gov.in.','https://soilhealth.dac.gov.in',array['farming']::text[],array['soil','மண்']::text[],4,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pm-jay','central','health','ஆயுஷ்மான் பாரத் – PM-JAY','Ayushman Bharat – PM-JAY','தேசிய சுகாதார ஆணையம்','National Health Authority','தகுதியுள்ள குடும்பத்துக்கு ஆண்டுக்கு ₹5 லட்சம் வரை இலவச மருத்துவமனைச் சிகிச்சை (பட்டியலிடப்பட்ட மருத்துவமனைகளில்).','Free hospital treatment up to ₹5 lakh per family per year at empanelled hospitals.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":300000,"communities":null}'::jsonb,'["aadhaar","ration","mobile"]'::jsonb,'pmjay.gov.in-இல் ''Am I Eligible'' மூலம் சரிபார்த்து, அருகிலுள்ள ஆயுஷ்மான் மித்ரா / CSC-இல் அட்டை பெறலாம்.','Check ''Am I Eligible'' on pmjay.gov.in, then get the card at an Ayushman Mitra desk or CSC.','https://pmjay.gov.in',array['health','insurance']::text[],array['ayushman','pmjay','ஆயுஷ்மான்','health insurance','மருத்துவக் காப்பீடு']::text[],10,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('cmchis','state','health','முதலமைச்சரின் விரிவான மருத்துவக் காப்பீட்டுத் திட்டம் (CMCHIS)','Chief Minister''s Comprehensive Health Insurance Scheme (CMCHIS)','தமிழ்நாடு சுகாதாரத் துறை / காப்பீட்டு நிறுவனம்','Tamil Nadu Health Dept. / insurance company','தகுதியுள்ள குடும்பங்களுக்கு ஆண்டுக்கு ₹5 லட்சம் வரை மருத்துவச் சிகிச்சைக் காப்பீடு.','Health-insurance cover up to ₹5 lakh a year for eligible families.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":120000,"communities":null}'::jsonb,'["aadhaar","ration","income","photo"]'::jsonb,'வருமானச் சான்றுடன் அருகிலுள்ள காப்பீட்டு உதவி மையம் / அரசு மருத்துவமனை.','With an income certificate, at the nearest insurance help desk or government hospital.','https://www.cmchistn.com',array['health','insurance']::text[],array['cmchis','கலைஞர் காப்பீடு','முதலமைச்சர் காப்பீடு','tn health insurance']::text[],9,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pmmvy','central','women','பிரதமர் மாத்ரு வந்தனா யோஜனா (PMMVY)','PM Matru Vandana Yojana (PMMVY)','பெண்கள் & குழந்தைகள் மேம்பாட்டு அமைச்சகம்','Ministry of Women & Child Development','கர்ப்பிணி, பாலூட்டும் தாய்மார்களுக்குத் தவணைகளில் பண உதவி (முதல் உயிருடன் பிறந்த குழந்தைக்கு).','Cash assistance in instalments for pregnant and lactating mothers (for the first living child).','{"minAge":19,"maxAge":null,"gender":"female","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","mobile"]'::jsonb,'அங்கன்வாடி மையம் அல்லது அருகிலுள்ள சுகாதார நிலையத்தில் பதிவு.','Register at your Anganwadi centre or nearest health facility.','https://pmmvy.wcd.gov.in',array['women','health','money']::text[],array['maternity','pregnant','கர்ப்பிணி','மகப்பேறு']::text[],7,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('tn-maternity','state','women','டாக்டர் முத்துலட்சுமி ரெட்டி மகப்பேறு நிதியுதவித் திட்டம்','Dr. Muthulakshmi Reddy Maternity Benefit Scheme','தமிழ்நாடு சுகாதாரத் துறை','Tamil Nadu Health Dept.','ஏழைக் கர்ப்பிணிகளுக்குப் பண உதவியும் ஊட்டச்சத்துப் பெட்டகமும்.','Cash assistance and a nutrition kit for poor pregnant women.','{"minAge":19,"maxAge":null,"gender":"female","occupations":null,"maxIncome":150000,"communities":null}'::jsonb,'["aadhaar","bank","income","mobile"]'::jsonb,'கிராம / நகர சுகாதாரச் செவிலியரிடம் கர்ப்பப் பதிவு (PICME) செய்யும்போது தகவல் கிடைக்கும்.','Details are given when the pregnancy is registered (PICME) with the village / urban health nurse.','https://tnhealth.tn.gov.in',array['women','health','money']::text[],array['maternity','முத்துலட்சுமி','மகப்பேறு','pregnancy']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pm-ujjwala','central','women','பிரதமர் உஜ்வலா யோஜனா (இலவச எரிவாயு இணைப்பு)','PM Ujjwala Yojana (LPG connection)','பெட்ரோலியம் & இயற்கை எரிவாயு அமைச்சகம்','Ministry of Petroleum & Natural Gas','வறுமைக் கோட்டுக்குக் கீழுள்ள குடும்பப் பெண்களுக்கு எரிவாயு இணைப்பு.','An LPG connection in the name of a woman from a poor household.','{"minAge":18,"maxAge":null,"gender":"female","occupations":null,"maxIncome":150000,"communities":null}'::jsonb,'["aadhaar","ration","bank","photo"]'::jsonb,'அருகிலுள்ள எரிவாயு விநியோகஸ்தர் அல்லது pmuy.gov.in.','Your nearest LPG distributor or pmuy.gov.in.','https://www.pmuy.gov.in',array['women','housing']::text[],array['ujjwala','gas','எரிவாயு','சிலிண்டர்']::text[],5,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('sukanya','central','women','சுகன்யா சம்ரித்தி கணக்கு','Sukanya Samriddhi Account','அஞ்சலகம் / அங்கீகரிக்கப்பட்ட வங்கிகள்','Post offices / authorised banks','பெண் குழந்தையின் கல்வி, திருமணச் செலவுக்கு அரசு ஆதரவு சிறுசேமிப்பு – நல்ல வட்டி விகிதம்.','A government-backed small-savings account for a girl child''s education and marriage, with an attractive interest rate.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["birth","aadhaar","photo"]'::jsonb,'பெண் குழந்தைக்கு 10 வயதுக்குள் அஞ்சலகம் அல்லது வங்கியில் கணக்குத் தொடங்கலாம்.','Open at a post office or bank before the girl turns 10.','https://www.nsiindia.gov.in',array['women','savings','education']::text[],array['sukanya','சுகன்யா','girl child','பெண் குழந்தை']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('apy','central','seniors','அடல் ஓய்வூதியத் திட்டம் (APY)','Atal Pension Yojana (APY)','PFRDA / வங்கிகள்','PFRDA / banks','60 வயதுக்குப் பிறகு மாதம் ₹1,000 முதல் ₹5,000 வரை உறுதியான ஓய்வூதியம்.','A guaranteed monthly pension of ₹1,000 to ₹5,000 after age 60.','{"minAge":18,"maxAge":40,"gender":"any","occupations":["worker","selfemployed","employee","farmer","homemaker","unemployed","student","other"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","mobile"]'::jsonb,'உங்கள் வங்கிக் கிளையில் அல்லது நெட் பேங்கிங் மூலம் சேரலாம்.','Join at your bank branch or through net banking.','https://www.jansuraksha.gov.in',array['pension','savings']::text[],array['atal pension','அடல்','pension','ஓய்வூதியம்']::text[],7,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pmjjby','central','seniors','பிரதமர் ஜீவன் ஜோதி பீமா யோஜனா (PMJJBY)','PM Jeevan Jyoti Bima Yojana (PMJJBY)','வங்கிகள் / காப்பீட்டு நிறுவனங்கள்','Banks / insurers','ஆண்டுக்கு மிகக் குறைந்த பிரீமியத்தில் ₹2 லட்சம் ஆயுள் காப்பீடு.','₹2 lakh life cover for a low annual premium.','{"minAge":18,"maxAge":50,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank"]'::jsonb,'உங்கள் வங்கிக் கணக்கு மூலம் தானியங்கிப் பிரீமியத்துடன் சேரலாம்.','Join through your bank account with auto-debit of the premium.','https://www.jansuraksha.gov.in',array['insurance','savings']::text[],array['jeevan jyoti','life insurance','ஆயுள் காப்பீடு']::text[],5,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pmsby','central','seniors','பிரதமர் சுரக்ஷா பீமா யோஜனா (PMSBY)','PM Suraksha Bima Yojana (PMSBY)','வங்கிகள் / காப்பீட்டு நிறுவனங்கள்','Banks / insurers','விபத்து மரணம் / முழு ஊனத்துக்கு ₹2 லட்சம் வரை காப்பீடு; மிகக் குறைந்த ஆண்டுப் பிரீமியம்.','Accident cover up to ₹2 lakh for death or total disability, for a very low annual premium.','{"minAge":18,"maxAge":70,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank"]'::jsonb,'உங்கள் வங்கியில் ஆண்டுதோறும் தானியங்கிப் பிரீமியத்துடன் சேரலாம்.','Join at your bank with annual auto-debit.','https://www.jansuraksha.gov.in',array['insurance']::text[],array['suraksha bima','accident insurance','விபத்துக் காப்பீடு']::text[],5,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('mudra','central','business','பிரதமர் முத்ரா கடன் (PMMY)','PM MUDRA Yojana (PMMY)','MUDRA / வங்கிகள் & நிதி நிறுவனங்கள்','MUDRA / banks and NBFCs','சிறு தொழில்களுக்கு அடமானம் இல்லாத கடன் – சிசு, கிஷோர், தருண் பிரிவுகளில்.','Collateral-free loans for small businesses in Shishu, Kishor and Tarun categories.','{"minAge":18,"maxAge":null,"gender":"any","occupations":["selfemployed","unemployed","worker","homemaker","farmer"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","pan","bank","photo"]'::jsonb,'வங்கிக் கிளை அல்லது udyamimitra.in வழியாக விண்ணப்பம்; தொழில் திட்ட அறிக்கை தேவை.','Apply at a bank branch or via udyamimitra.in with a simple business plan.','https://www.mudra.org.in',array['business','loan']::text[],array['mudra','முத்ரா','business loan','தொழில் கடன்']::text[],9,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pm-svanidhi','central','business','பிரதமர் ஸ்வநிதி (தெருவோர வியாபாரிகள்)','PM SVANidhi (street vendors)','வீட்டுவசதி & நகர்ப்புற விவகார அமைச்சகம்','Ministry of Housing & Urban Affairs','தெருவோர வியாபாரிகளுக்குச் சிறு பணி மூலதனக் கடன்; சரியாகத் திருப்பிச் செலுத்தினால் அடுத்த கடன்.','A small working-capital loan for street vendors, with larger loans on timely repayment.','{"minAge":null,"maxAge":null,"gender":"any","occupations":["selfemployed","worker"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","mobile"]'::jsonb,'pmsvanidhi.mohua.gov.in அல்லது உங்கள் நகராட்சி / மாநகராட்சி அலுவலகம்.','pmsvanidhi.mohua.gov.in or your municipality / corporation office.','https://pmsvanidhi.mohua.gov.in',array['business','loan']::text[],array['street vendor','svanidhi','தெருவோர']::text[],5,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pm-vishwakarma','central','business','பிரதமர் விஸ்வகர்மா (கைவினைஞர்கள்)','PM Vishwakarma (artisans)','MSME அமைச்சகம்','Ministry of MSME','பாரம்பரியக் கைவினைஞர்களுக்குப் பயிற்சி, கருவிப் பெட்டி, குறைந்த வட்டிக் கடன்.','Training, a toolkit and low-interest credit for traditional artisans.','{"minAge":18,"maxAge":null,"gender":"any","occupations":["selfemployed","worker"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","mobile","photo"]'::jsonb,'pmvishwakarma.gov.in அல்லது CSC மையம் வழியாகப் பதிவு.','Register through pmvishwakarma.gov.in or a CSC.','https://pmvishwakarma.gov.in',array['business','skill','loan']::text[],array['vishwakarma','artisan','கைவினை','தச்சர்','தையல்']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('standup-india','central','business','ஸ்டாண்ட்-அப் இந்தியா','Stand-Up India','SIDBI / வங்கிகள்','SIDBI / banks','பட்டியல் சாதி / பழங்குடியினர், பெண் தொழில்முனைவோருக்குப் புதிய தொழில் தொடங்க ₹10 லட்சம் முதல் ₹1 கோடி வரை கடன்.','Bank loans of ₹10 lakh to ₹1 crore for SC/ST and women entrepreneurs starting a new enterprise.','{"minAge":18,"maxAge":null,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","pan","community","bank"]'::jsonb,'standupmitra.in வழியாக விண்ணப்பம்.','Apply through standupmitra.in.','https://www.standupmitra.in',array['business','loan','women']::text[],array['standup','women entrepreneur','பெண் தொழில்முனைவோர்']::text[],4,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pmay-g','central','housing','பிரதமர் ஆவாஸ் யோஜனா – கிராமம்','PM Awaas Yojana – Gramin','ஊரக வளர்ச்சி அமைச்சகம்','Ministry of Rural Development','கிராமப்புறத்தில் வீடற்றோர் / கச்சா வீடுள்ளோருக்குப் பக்கா வீடு கட்ட நிதி உதவி.','Financial help to build a pucca house for rural families without a house or in a kutcha house.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":300000,"communities":null}'::jsonb,'["aadhaar","ration","bank","land"]'::jsonb,'கிராம ஊராட்சி / வட்டார வளர்ச்சி அலுவலகம் வழியாகப் பயனாளர் பட்டியலில் சேர்க்கப்படும்.','Selection is through the gram panchayat / block development office beneficiary list.','https://rural.gov.in',array['housing']::text[],array['awas','house','வீடு','ஆவாஸ்']::text[],7,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pmay-u','central','housing','பிரதமர் ஆவாஸ் யோஜனா – நகரம்','PM Awaas Yojana – Urban','வீட்டுவசதி & நகர்ப்புற விவகார அமைச்சகம்','Ministry of Housing & Urban Affairs','நகர்ப்புற ஏழை, நடுத்தரக் குடும்பங்களுக்கு வீடு கட்ட / வாங்க வட்டி மானியம் அல்லது நிதி உதவி.','Interest subsidy or financial help for urban poor and middle-income families to build or buy a house.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":1800000,"communities":null}'::jsonb,'["aadhaar","income","bank","land"]'::jsonb,'pmay-urban.gov.in அல்லது உங்கள் நகராட்சி அலுவலகம்.','pmay-urban.gov.in or your municipal office.','https://pmay-urban.gov.in',array['housing','loan']::text[],array['awas urban','home loan subsidy','வீட்டுக் கடன் மானியம்']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('ignoaps','central','seniors','இந்திரா காந்தி தேசிய முதியோர் ஓய்வூதியம் (NSAP)','Indira Gandhi National Old Age Pension (NSAP)','ஊரக வளர்ச்சி அமைச்சகம் / மாநில வருவாய்த் துறை','Ministry of Rural Development / state revenue dept.','வறுமைக் கோட்டுக்குக் கீழுள்ள முதியோருக்கு மாதாந்திர ஓய்வூதியம்.','A monthly pension for elderly people from poor (BPL) households.','{"minAge":60,"maxAge":null,"gender":"any","occupations":null,"maxIncome":100000,"communities":null}'::jsonb,'["aadhaar","age","bank","ration","photo"]'::jsonb,'வட்டாட்சியர் (தாலுகா) அலுவலகம் அல்லது இ-சேவை மையத்தில் விண்ணப்பம்; UMANG செயலியிலும் NSAP சேவை உண்டு.','Apply at the taluk office or an e-Sevai centre; the NSAP service is also on the UMANG app.','https://rural.gov.in',array['pension','money']::text[],array['old age pension','முதியோர் ஓய்வூதியம்','ignoaps','nsap']::text[],9,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('tn-oap','state','seniors','தமிழ்நாடு முதியோர் உதவித்தொகை','Tamil Nadu old-age assistance','வருவாய்த் துறை – தமிழ்நாடு அரசு','Revenue Dept., Government of Tamil Nadu','ஆதரவற்ற முதியோருக்கு மாதாந்திர உதவித்தொகை.','Monthly assistance for destitute elderly people.','{"minAge":60,"maxAge":null,"gender":"any","occupations":null,"maxIncome":100000,"communities":null}'::jsonb,'["aadhaar","age","bank","ration","photo"]'::jsonb,'இ-சேவை மையம் அல்லது வட்டாட்சியர் அலுவலகத்தில் விண்ணப்பம்; கள ஆய்வுக்குப் பின் அனுமதி.','Apply at an e-Sevai centre or taluk office; sanctioned after a field inquiry.','https://www.tnesevai.tn.gov.in',array['pension','money']::text[],array['முதியோர் உதவித்தொகை','old age pension tn','ஆதரவற்ற']::text[],8,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('udid','central','health','மாற்றுத்திறனாளி தனித்துவ அடையாள அட்டை (UDID)','Unique Disability ID (UDID)','மாற்றுத்திறனாளிகள் அதிகாரமளிப்புத் துறை','Dept. of Empowerment of Persons with Disabilities','நாடு முழுவதும் செல்லுபடியாகும் மாற்றுத்திறன் அடையாளம்; திட்டங்கள், சலுகைகளைப் பெற அடிப்படை.','A nation-wide disability ID that is the basis for benefits and concessions.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","photo","disability","mobile"]'::jsonb,'swavlambancard.gov.in-இல் விண்ணப்பித்து, மருத்துவ மதிப்பீட்டுக்குச் செல்ல வேண்டும்.','Apply on swavlambancard.gov.in and attend the medical assessment.','https://www.swavlambancard.gov.in',array['health','money']::text[],array['udid','disability','மாற்றுத்திறனாளி','ஊனம்']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pudhumai-penn','state','education','புதுமைப் பெண் திட்டம்','Pudhumai Penn scheme','உயர்கல்வித் துறை – தமிழ்நாடு அரசு','Higher Education Dept., Government of Tamil Nadu','அரசுப் பள்ளியில் 6–12 படித்து உயர்கல்வி பயிலும் மாணவிகளுக்கு மாதம் ₹1,000 உதவித்தொகை.','₹1,000 a month for girls who studied classes 6–12 in government schools and are in higher education.','{"minAge":16,"maxAge":30,"gender":"female","occupations":["student"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","marks","photo"]'::jsonb,'படிக்கும் கல்லூரி வழியாக விண்ணப்பம்.','Apply through the college you study in.','https://myscheme.gov.in/schemes/pudhumai-penn-scheme',array['education','money','women']::text[],array['pudhumai penn','புதுமைப் பெண்','1000 college girls']::text[],9,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('tamil-pudhalvan','state','education','தமிழ்ப் புதல்வன் திட்டம்','Tamil Pudhalvan scheme','உயர்கல்வித் துறை – தமிழ்நாடு அரசு','Higher Education Dept., Government of Tamil Nadu','அரசுப் பள்ளியில் 6–12 படித்து உயர்கல்வி பயிலும் மாணவர்களுக்கு மாதம் ₹1,000 உதவித்தொகை.','₹1,000 a month for boys who studied classes 6–12 in government schools and are in higher education.','{"minAge":16,"maxAge":30,"gender":"male","occupations":["student"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","marks","photo"]'::jsonb,'படிக்கும் கல்லூரி வழியாக விண்ணப்பம்.','Apply through the college you study in.','https://www.tn.gov.in',array['education','money']::text[],array['tamil pudhalvan','தமிழ்ப் புதல்வன்']::text[],7,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('nsp-scholarships','central','education','தேசிய உதவித்தொகைத் தளம் (NSP) – கல்வி உதவித்தொகைகள்','National Scholarship Portal (NSP) – scholarships','கல்வி அமைச்சகம் / சமூக நீதி / சிறுபான்மையினர் நல அமைச்சகங்கள்','Ministries of Education, Social Justice and Minority Affairs','SC/ST/OBC, சிறுபான்மையினர், ஏழை மாணவர்களுக்கு மெட்ரிக்குக்குப் பிந்தைய உதவித்தொகைகள் – ஒரே தளத்தில்.','Post-matric and other scholarships for SC/ST/OBC, minority and low-income students on a single portal.','{"minAge":null,"maxAge":null,"gender":"any","occupations":["student"],"maxIncome":250000,"communities":null}'::jsonb,'["aadhaar","bank","income","community","marks","photo"]'::jsonb,'scholarships.gov.in-இல் ஒருமுறைப் பதிவு (OTR) செய்து, தகுதியான உதவித்தொகைக்கு விண்ணப்பிக்கவும்; கல்வி நிறுவனம் சரிபார்க்கும்.','Do one-time registration on scholarships.gov.in and apply; your institution verifies it.','https://scholarships.gov.in',array['education','money']::text[],array['scholarship','nsp','உதவித்தொகை','கல்வி உதவி']::text[],10,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('pm-vidyalaxmi','central','education','பிரதமர் வித்யாலட்சுமி (கல்விக் கடன்)','PM-Vidyalaxmi (education loan)','உயர்கல்வித் துறை – கல்வி அமைச்சகம்','Dept. of Higher Education, Ministry of Education','தகுதியுள்ள உயர்கல்வி நிறுவனங்களில் சேரும் மாணவர்களுக்கு அடமானம் / உத்தரவாதம் இல்லாத கல்விக் கடன் ஆதரவு.','Collateral- and guarantor-free education-loan support for students admitted to eligible institutions.','{"minAge":17,"maxAge":null,"gender":"any","occupations":["student"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","marks","income","photo"]'::jsonb,'pmvidyalaxmi.co.in-இல் பொது விண்ணப்பம்.','Common application on pmvidyalaxmi.co.in.','https://pmvidyalaxmi.co.in',array['education','loan']::text[],array['education loan','கல்விக் கடன்','vidyalaxmi']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('tn-breakfast','state','education','முதலமைச்சரின் காலை உணவுத் திட்டம்','Chief Minister''s Breakfast Scheme','பள்ளிக் கல்வித் துறை – தமிழ்நாடு அரசு','School Education Dept., Government of Tamil Nadu','அரசுத் தொடக்கப் பள்ளி மாணவர்களுக்குப் பள்ளியிலேயே இலவசக் காலை உணவு. தனி விண்ணப்பம் தேவையில்லை.','Free breakfast at government primary schools. No separate application.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'[]'::jsonb,'குழந்தை படிக்கும் அரசுப் பள்ளியிலேயே கிடைக்கும்.','Available in the government school your child attends.','https://www.tn.gov.in',array['education']::text[],array['breakfast','காலை உணவு','school food']::text[],5,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('naan-mudhalvan','state','jobs','நான் முதல்வன் – திறன் மேம்பாடு','Naan Mudhalvan – skill development','தமிழ்நாடு திறன் மேம்பாட்டுக் கழகம்','Tamil Nadu Skill Development Corporation','மாணவர்கள், இளைஞர்களுக்கு இலவசத் திறன் பயிற்சி, வேலைவாய்ப்பு வழிகாட்டல்.','Free skill training and employability guidance for students and young people.','{"minAge":16,"maxAge":35,"gender":"any","occupations":["student","unemployed"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","marks","mobile"]'::jsonb,'naanmudhalvan.tn.gov.in-இல் பதிவு செய்யவும் அல்லது கல்லூரி வழியாக.','Register on naanmudhalvan.tn.gov.in or through your college.','https://www.naanmudhalvan.tn.gov.in',array['skill','jobs','education']::text[],array['naan mudhalvan','நான் முதல்வன்','skill training','திறன் பயிற்சி']::text[],8,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('skill-india','central','jobs','ஸ்கில் இந்தியா / பிரதமர் கௌஷல் விகாஸ் (PMKVY)','Skill India / PM Kaushal Vikas Yojana (PMKVY)','திறன் மேம்பாடு & தொழில்முனைவு அமைச்சகம்','Ministry of Skill Development & Entrepreneurship','இளைஞர்களுக்கு அரசு அங்கீகாரச் சான்றிதழுடன் குறுகிய காலத் திறன் பயிற்சி.','Short-term skill training with a government-recognised certificate for young people.','{"minAge":15,"maxAge":45,"gender":"any","occupations":["student","unemployed","worker"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","photo"]'::jsonb,'skillindiadigital.gov.in-இல் பயிற்சி மையம் / படிப்பைத் தேர்ந்தெடுக்கவும்.','Choose a course and centre on skillindiadigital.gov.in.','https://www.skillindiadigital.gov.in',array['skill','jobs']::text[],array['pmkvy','skill india','திறன்']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('tn-free-bus','state','women','மகளிர் கட்டணமில்லாப் பேருந்துப் பயணம் (விடியல் பயணம்)','Free bus travel for women (Vidiyal Payanam)','போக்குவரத்துத் துறை – தமிழ்நாடு அரசு','Transport Dept., Government of Tamil Nadu','நகரப் பேருந்துகளில் (குறிப்பிட்ட வகை) பெண்களுக்கு இலவசப் பயணம். விண்ணப்பம் இல்லை.','Free travel for women on notified ordinary town buses. No application.','{"minAge":null,"maxAge":null,"gender":"female","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'[]'::jsonb,'பேருந்தில் ஏறிப் பயணம் செய்யலாம்; நடத்துநரிடம் விவரம் கேட்கலாம்.','Just board; ask the conductor for details.','https://www.tn.gov.in',array['women']::text[],array['free bus','இலவசப் பேருந்து','மகளிர் பேருந்து','vidiyal']::text[],7,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('magalir-urimai','state','women','மகளிர் உரிமைத் தொகை','Magalir Urimai Thogai (women''s entitlement)','வருவாய்த் துறை / சமூக நலத் துறை – தமிழ்நாடு அரசு','Revenue / Social Welfare Dept., Government of Tamil Nadu','தகுதியுள்ள குடும்பத் தலைவிக்கு மாதம் ₹1,000 வங்கிக் கணக்கில்.','₹1,000 a month into the bank account of an eligible woman head of family.','{"minAge":21,"maxAge":null,"gender":"female","occupations":["homemaker","worker","selfemployed","farmer","unemployed","senior","other"],"maxIncome":250000,"communities":null}'::jsonb,'["aadhaar","ration","bank","mobile"]'::jsonb,'அறிவிக்கப்படும் சிறப்பு முகாம்கள் அல்லது இ-சேவை மூலம் விண்ணப்பம்; மேல்முறையீட்டு வசதி உண்டு.','Through announced camps or e-Sevai; an appeal option exists.','https://www.tn.gov.in',array['women','money']::text[],array['urimai','உரிமைத் தொகை','1000 rupees women','magalir']::text[],10,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('jan-dhan','central','business','பிரதமர் ஜன் தன் வங்கிக் கணக்கு','PM Jan Dhan bank account','நிதிச் சேவைகள் துறை','Dept. of Financial Services','குறைந்தபட்ச இருப்பு இல்லாத வங்கிக் கணக்கு; RuPay அட்டை, விபத்துக் காப்பீடு.','A zero-balance bank account with a RuPay card and accident cover.','{"minAge":10,"maxAge":null,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","photo","mobile"]'::jsonb,'எந்த வங்கிக் கிளையிலும் அல்லது வங்கி மித்ரா மூலம்.','At any bank branch or via a Bank Mitra.','https://pmjdy.gov.in',array['savings']::text[],array['jan dhan','zero balance','ஜன் தன்','bank account']::text[],6,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('tn-pds','state','welfare','பொது விநியோகத் திட்டம் – குடும்ப (ரேஷன்) அட்டை','Public Distribution System – family (ration) card','உணவு & நுகர்பொருள் வழங்கல் துறை – தமிழ்நாடு அரசு','Food & Civil Supplies Dept., Government of Tamil Nadu','மானிய விலையில் அரிசி உள்ளிட்ட பொருட்கள்; பல திட்டங்களுக்கு அடிப்படை ஆவணம்.','Subsidised rice and other items, and a base document for many schemes.','{"minAge":null,"maxAge":null,"gender":"any","occupations":null,"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","address","photo","mobile"]'::jsonb,'tnpds.gov.in-இல் புதிய அட்டை / திருத்தம் / உறுப்பினர் சேர்க்கை விண்ணப்பம்.','Apply on tnpds.gov.in for a new card, a correction or adding a member.','https://www.tnpds.gov.in',array['money']::text[],array['ration card','family card','ரேஷன்','குடும்ப அட்டை','smart card']::text[],9,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('eshram','central','welfare','இ-ஷ்ரம் – அமைப்புசாரா தொழிலாளர் பதிவு','e-Shram – unorganised workers registration','தொழிலாளர் & வேலைவாய்ப்பு அமைச்சகம்','Ministry of Labour & Employment','அமைப்புசாராத் தொழிலாளர்களுக்கு அடையாள அட்டை, விபத்துக் காப்பீடு, எதிர்காலத் திட்டங்களுக்கான தரவுத்தளம்.','An ID card, accident cover and entry into a database used for future welfare schemes.','{"minAge":16,"maxAge":59,"gender":"any","occupations":["worker","farmer","selfemployed"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","mobile"]'::jsonb,'eshram.gov.in-இல் ஆதார் OTP மூலம் அல்லது CSC-இல் இலவசப் பதிவு.','Free registration on eshram.gov.in with an Aadhaar OTP or at a CSC.','https://eshram.gov.in',array['insurance','money']::text[],array['eshram','e-shram','இ-ஷ்ரம்','unorganised worker','கூலி']::text[],8,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
insert into public.schemes (id,level,category,title_ta,title_en,department_ta,department_en,benefit_ta,benefit_en,eligibility_json,documents_json,apply_method_ta,apply_method_en,official_url,needs,keywords,popularity,status,last_verified_at) values ('tn-labour-welfare','state','welfare','தமிழ்நாடு தொழிலாளர் நல வாரியங்கள்','Tamil Nadu labour welfare boards','தொழிலாளர் நலத் துறை – தமிழ்நாடு அரசு','Labour Welfare Dept., Government of Tamil Nadu','பதிவு பெற்ற உடலுழைப்பு, கட்டுமானம் உள்ளிட்ட தொழிலாளர்களுக்குக் கல்வி, திருமணம், மகப்பேறு, ஓய்வூதிய உதவிகள்.','Education, marriage, maternity and pension assistance for registered manual, construction and other workers.','{"minAge":18,"maxAge":60,"gender":"any","occupations":["worker"],"maxIncome":null,"communities":null}'::jsonb,'["aadhaar","bank","photo","mobile"]'::jsonb,'labour.tn.gov.in-இல் வாரியத்தில் பதிவு செய்து அடையாள அட்டை பெறவும்.','Register with the relevant board on labour.tn.gov.in and get an ID card.','https://labour.tn.gov.in',array['money','education']::text[],array['welfare board','நல வாரியம்','construction worker','கட்டுமானத் தொழிலாளி']::text[],7,'active',null) on conflict (id) do update set level=excluded.level,category=excluded.category,title_ta=excluded.title_ta,title_en=excluded.title_en,department_ta=excluded.department_ta,department_en=excluded.department_en,benefit_ta=excluded.benefit_ta,benefit_en=excluded.benefit_en,eligibility_json=excluded.eligibility_json,documents_json=excluded.documents_json,apply_method_ta=excluded.apply_method_ta,apply_method_en=excluded.apply_method_en,official_url=excluded.official_url,needs=excluded.needs,keywords=excluded.keywords,popularity=excluded.popularity,status=excluded.status,last_verified_at=excluded.last_verified_at;
